def identity_matrix(n):
    return [[1 if i == j else 0 for j in range(n)] for i in range(n)]

def multiply_matrices(A, B, MOD):
    n = len(A)
    C = identity_matrix(n)
    for i in range(n):
        for j in range(n):
            C[i][j] = sum(A[i][k] * B[k][j] % MOD for k in range(n)) % MOD
    return C

def matrix_power(matrix, power, MOD):
    n = len(matrix)
    result = identity_matrix(n)
    base = matrix

    while power > 0:
        if power % 2 == 1:
            result = multiply_matrices(result, base, MOD)
        base = multiply_matrices(base, base, MOD)
        power //= 2

    return result

def sum_of_matrix(matrix):
    return sum(sum(row) for row in matrix)

def solve(inputs):
    A = inputs['A']
    B = inputs['B']
    C = inputs['C']
    D = inputs['D']
    MOD = inputs['MOD']
    K = inputs['K']

    M = [[A, B], [C, D]]
    M_power_k = matrix_power(M, K, MOD)
    result_sum = sum_of_matrix(M_power_k)

    return result_sum

